nta.declaration:
urgent chan dummy;
urgent chan start;
chan finish;

// ——————————————————————————————
// Model parameters
// ——————————————————————————————
const int NUM_ACTORS = 11;
const int NUM_EDGES = 22;
const int MAX_TOKENS = 1;

// ——————————————————————————————
// Typedefs for indices
// ——————————————————————————————
typedef int[1, NUM_ACTORS] actor_t;
typedef int[1, NUM_EDGES] edges_t;
typedef int[0, MAX_TOKENS-1] index_t;

// ——————————————————————————————
// Edge metadata (global)
// ——————————————————————————————
typedef struct {
  actor_t from;   // source actor
  actor_t to;     // destination actor
} edge_t;

edge_t edges[edges_t] ={
  { 1, 2 }, // A -> B_start
  { 1, 3 }, // A -> F_start
  { 2, 4 }, // B_start -> B
  { 5, 6 }, // C_start -> C
  { 7, 8 }, // D_start -> D
  { 9, 10 }, // E_start -> E
  { 3, 11 }, // F_start -> F
  { 4, 2 }, // B -> B_start
  { 6, 5 }, // C -> C_start
  { 8, 7 }, // D -> D_start
  { 10, 9 }, // E -> E_start
  { 11, 3 }, // F -> F_start
  { 4, 5 }, // B -> C_start
  { 6, 7 }, // C -> D_start
  { 8, 9 }, // D -> E_start
  { 10, 3 }, // E -> F_start
  { 5, 2 }, // C_start -> B_start
  { 7, 5 }, // D_start -> C_start
  { 9, 7 }, // E_start -> D_start
  { 3, 9 }, // F_start -> E_start
  { 2, 1 }, // B_start -> A
  { 3, 1 } // F_start -> A
};


// ——————————————————————————————————————————
// Token buffers
// ——————————————————————————————————————————
// edge_token[e][slot]
// slot ∈ {0} only
bool edge_token[NUM_EDGES+1][MAX_TOKENS] =  {
  /* unused index 0 */ { false },
  /* A -> B_start */ { true },
  /* A -> F_start */ { true },
  /* B_start -> B */ { false },
  /* C_start -> C */ { false },
  /* D_start -> D */ { false },
  /* E_start -> E */ { false },
  /* F_start -> F */ { false },
  /* B -> B_start */ { true },
  /* C -> C_start */ { true },
  /* D -> D_start */ { true },
  /* E -> E_start */ { true },
  /* F -> F_start */ { true },
  /* B -> C_start */ { true },
  /* C -> D_start */ { true },
  /* D -> E_start */ { true },
  /* E -> F_start */ { true },
  /* C_start -> B_start */ { true },
  /* D_start -> C_start */ { true },
  /* E_start -> D_start */ { true },
  /* F_start -> E_start */ { true },
  /* B_start -> A */ { true },
  /* F_start -> A */ { true }
};

// ——————————————————————————————————————————
// Actor ready-flags
// ——————————————————————————————————————————
// actor_ready[a][slot] = true iff all incoming edges into a carry a token
bool actor_ready[NUM_ACTORS+1][MAX_TOKENS] = {
  /* unused actor 0 */ { false },
  /* actor 1 (A) */ { true },
  /* actor 2 (B_start) */ { false },
  /* actor 3 (F_start) */ { false },
  /* actor 4 (B) */ { false },
  /* actor 5 (C_start) */ { false },
  /* actor 6 (C) */ { false },
  /* actor 7 (D_start) */ { false },
  /* actor 8 (D) */ { false },
  /* actor 9 (E_start) */ { false },
  /* actor 10 (E) */ { false },
  /* actor 11 (F) */ { false }
};


// ——————————————————————————————
// Query: has actor `act` all inputs at slot `idx`?
// (i.e. is it *not* empty?)
// ——————————————————————————————
bool empty(actor_t act, index_t idx) {
  return not actor_ready[act][idx];
}

// ——————————————————————————————
// Produce on *all* outgoing edges of `act`, then update downstream flags
// ——————————————————————————————
void produce_actor(actor_t act, index_t idx) {
  actor_t dst;
  bool all_in;
  for (e : edges_t) {
    if (edges[e].from == act) {
      // place the token
      edge_token[e][idx] = true;
      // recompute readiness for the destination actor
      dst = edges[e].to;
      all_in = true;
      for (er : edges_t) {
        if (edges[er].to == dst && not edge_token[er][idx]) {
          all_in = false;
        }
      }
      actor_ready[dst][idx] = all_in;
    }
  }
}


// ——————————————————————————————
// Consume incoming token for `act`, then update its own flag
// ——————————————————————————————
void consume_actor(actor_t act, index_t idx) {
  // Local variables must be declared up front
  bool      all_in;
  index_t   next;

  // clear our own readiness at the current slot
  actor_ready[act][idx] = false;

  // clear tokens on all incoming edges at current slot
  for (e : edges_t) {
    if (edges[e].to == act) {
      edge_token[e][idx] = false;
    }
  }

  // compute the next buffer slot (circular)
  next = (idx + 1) % MAX_TOKENS;

  // check if *all* incoming edges have a token at 'next'
  all_in = true;
  for (er : edges_t) {
    if (edges[er].to == act && not edge_token[er][next]) {
      all_in = false;
    }
  }

  // u pdate readiness for the next slot
  actor_ready[act][next] = all_in;
}

template.declaration:
clock r;
int m = -1;
int n = 0;

nta.system:
// Actor ID definitions
actor_t id1 = 1; // A
actor_t id2 = 2; // B_start
actor_t id3 = 3; // F_start
actor_t id4 = 4; // B
actor_t id5 = 5; // C_start
actor_t id6 = 6; // C
actor_t id7 = 7; // D_start
actor_t id8 = 8; // D
actor_t id9 = 9; // E_start
actor_t id10 = 10; // E
actor_t id11 = 11; // F

// WCET ranges per actor
const int LOW_1 = 983, HIGH_1 = 983; // A
const int LOW_2 = 0, HIGH_2 = 0; // B_start
const int LOW_3 = 0, HIGH_3 = 0; // F_start
const int LOW_4 = 67, HIGH_4 = 67; // B
const int LOW_5 = 0, HIGH_5 = 0; // C_start
const int LOW_6 = 94, HIGH_6 = 94; // C
const int LOW_7 = 0, HIGH_7 = 0; // D_start
const int LOW_8 = 632, HIGH_8 = 632; // D
const int LOW_9 = 0, HIGH_9 = 0; // E_start
const int LOW_10 = 4940, HIGH_10 = 4940; // E
const int LOW_11 = 261, HIGH_11 = 261; // F

// Actor instantiations
actorA = ActorStart(id1, LOW_1, HIGH_1);
actorBs = Actor(id2, LOW_2, HIGH_2);
actorFs = Actor(id3, LOW_3, HIGH_3);
actorB = Actor(id4, LOW_4, HIGH_4);
actorCs = Actor(id5, LOW_5, HIGH_5);
actorC = Actor(id6, LOW_6, HIGH_6);
actorDs = Actor(id7, LOW_7, HIGH_7);
actorD = Actor(id8, LOW_8, HIGH_8);
actorEs = Actor(id9, LOW_9, HIGH_9);
actorE = Actor(id10, LOW_10, HIGH_10);
actorF = ActorFinish(id11, LOW_11, HIGH_11);

system actorA, actorBs, actorFs, actorB, actorCs, actorC, actorDs, actorD, actorEs, actorE, actorF, Dummy, Timer;
